def chain_follows_chain(WELL_FORMED):
    tokens = []
    current_word = ''
    for c in WELL_FORMED:
        if current_word:
            tokens.append(current_word)
            current_word = ''
        current_word += c
    if not current_word:
        return ''

    chain = []
    for token in tokens:
        if token == 'w':
            chain.append('w')
        else:
            chain.append(token)

    return ','.join(chain)
